import pathlib,json,subprocess,datetime
R=pathlib.Path('/var/lib/twin-release/astra-compatible-20261028')
assert(R/'read-roles-started.json').exists()
d=json.loads(subprocess.check_output(['docker','inspect','next-app'],text=True))[0]
assert d['Image']=='sha256:fccf205a34fe002c6344062305128f6b302a2e1e0c5d92caf7beac30d2a79c95'
s="const assert=require('assert/strict'),fs=require('fs'),crypto=require('crypto');\n(async()=>{\nconst base='https://dashboard.tgaiclone.xyz';\nconst origin=process.env.DASHBOARD_PUBLIC_ORIGIN||'https://dashboard.tgaiclone.xyz',host=new URL(origin).host;\nassert(process.env.DASHBOARD_ALLOW_LEGACY_ADMIN_SESSIONS!=='1');\nassert(process.env.SUPABASE_URL.replace(/\\/$/,'')==='https://aouaenqayfltoqrmpitg.supabase.co');\nconst manifest=JSON.parse(fs.readFileSync('/app/.next/server/server-reference-manifest.json','utf8'));\nconst actions=Object.entries(manifest.node).filter(([id,v])=>v.filename==='app/login/actions.ts'&&v.exportedName==='logout');assert.equal(actions.length,1);\nconst action=actions[0][0],tokens=[];\nasync function rpc(name,t){const r=await fetch(process.env.SUPABASE_URL+'/rest/v1/rpc/'+name,{method:'POST',headers:{apikey:process.env.SUPABASE_SERVICE_KEY,Authorization:'Bearer '+process.env.SUPABASE_SERVICE_KEY,'Content-Type':'application/json'},body:JSON.stringify({p_session_hash:crypto.createHash('sha256').update(t).digest('hex')}),signal:AbortSignal.timeout(10000)});assert(r.ok,'Session RPC failed');return await r.json();}\nasync function login(){const r=await fetch(base+'/admin-auth',{method:'POST',headers:{Host:host,Origin:origin,'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({password:process.env.DASHBOARD_PASSWORD,next:'/onlyfans/accounts'}),redirect:'manual',signal:AbortSignal.timeout(15000)});assert.equal(r.status,303,'Admin login redirect');const match=r.headers.get('set-cookie')?.match(/allie_admin_session=(owner_[a-f0-9]{64})/);assert(match,'Server session cookie missing');tokens.push(match[1]);assert(await rpc('dashboard_owner_session_verify',match[1]));return match[1];}\nasync function page(token){const r=await fetch(base+'/onlyfans/accounts',{headers:{Host:host,Cookie:'allie_admin_session='+token},redirect:'manual',signal:AbortSignal.timeout(20000)});await r.arrayBuffer();return r.status;}\nasync function logout(token){const r=await fetch(base+'/onlyfans/accounts',{method:'POST',headers:{Host:host,Origin:origin,Cookie:'allie_admin_session='+token,'Next-Action':action,'Content-Type':'text/plain;charset=UTF-8',Accept:'text/x-component'},body:'[]',redirect:'manual',signal:AbortSignal.timeout(15000)});await r.arrayBuffer();assert([200,303].includes(r.status),'Logout action failed');return r.status;}\ntry{const a=await login(),b=await login();assert.equal(await page(b),200,'Authenticated account page unavailable');\nconst logoutStatus=await logout(a);assert.equal(await rpc('dashboard_owner_session_verify',a),false,'Logged-out session remained valid');assert.equal(await rpc('dashboard_owner_session_verify',b),true,'Other session was revoked');const replay=await page(a);assert([302,303,307,308,401,403].includes(replay),'Logged-out replay accepted');assert.equal(await page(b),200,'Other session stopped working');await logout(b);assert.equal(await rpc('dashboard_owner_session_verify',b),false);\nconsole.log(JSON.stringify({adminLogin:true,logoutAction:true,logoutStatus,replayStatus:replay,otherSessionPreserved:true,legacyCompatibility:false,testSessionsRemoved:true,source:process.env.GIT_SHA}));\n}finally{for(const t of tokens)await rpc('dashboard_owner_session_revoke',t).catch(()=>{});}\n})().catch(error=>{console.error(JSON.stringify({stage:'session-smoke',type:error.name,message:error.message}));process.exitCode=1;});"
r=subprocess.run(['docker','exec','-i','next-app','node'],input=s,text=True,capture_output=True,timeout=150)
(R/'production-session-smoke.log').write_text(r.stdout+r.stderr)
assert r.returncode==0,r.stderr
proof=json.loads(r.stdout);proof['at']=datetime.datetime.now(datetime.timezone.utc).isoformat()
(R/'production-session-smoke.json').write_text(json.dumps(proof,indent=2));print(json.dumps(proof))
